export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const BASE_TYPE_ALLOWANCE = 3;
const NO_SPHINX_SCORE = 0;
const BASE_SCORE = 2;
const BEYOND_ALLOWANCE_SCORE = 3;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;

  const distinctTypeCount = new Set(army.map((card) => card.monster)).size;

  return distinctTypeCount > BASE_TYPE_ALLOWANCE
    ? BEYOND_ALLOWANCE_SCORE
    : BASE_SCORE;
};

