6	const SPHINX = "sphinx";
7	
8	const TYPE_ALLOWANCE = 3;
9	const NO_SPHINX_SCORE = 0;
10	
11	/** Within the allowance the Sphinx scores 1, plus 1 for the company it keeps. */
12	const ALLOWANCE_SCORE = 2;
13	
14	const POINTS_PER_TYPE_BEYOND_ALLOWANCE = 2;
15	
16	/**
17	 * The Sphinx's own point is already earned inside the allowance, so the
18	 * beyond-allowance formula must not award it a second time.
19	 */
20	const SPHINX_POINT_ALREADY_COUNTED = 1;
21	
22	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
23	
24	const countDistinctTypes = (army: Card[]): number =>
25	  new Set(army.map((card) => card.monster)).size;
26	
27	const scoreBeyondAllowance = (distinctTypeCount: number): number =>
28	  POINTS_PER_TYPE_BEYOND_ALLOWANCE * (distinctTypeCount - TYPE_ALLOWANCE) -
29	  SPHINX_POINT_ALREADY_COUNTED;
30	
31	export const scoreArmy = (army: Card[]): number => {
32	  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;
33	
34	  const distinctTypeCount = countDistinctTypes(army);
35	
36	  return distinctTypeCount > TYPE_ALLOWANCE
37	    ? scoreBeyondAllowance(distinctTypeCount)
38	    : ALLOWANCE_SCORE;
39	};

