};

const SPHINX = "sphinx";

const SPHINX_POINT = 1;
const SPHINX_ITSELF = 1;
const THREE_TYPES = 3;
const POINTS_PER_TYPE_BEYOND_THREE = 2;
const POINTS_WITHIN_THREE_TYPES = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const scoreTypeVariety = (typesBesidesThisSphinx: number): number =>
  typesBesidesThisSphinx > THREE_TYPES
    ? POINTS_PER_TYPE_BEYOND_THREE * (typesBesidesThisSphinx - THREE_TYPES)
    : POINTS_WITHIN_THREE_TYPES;

const scoreSphinx = (otherCards: Card[]): number =>
  SPHINX_POINT + scoreTypeVariety(countDistinctTypes(otherCards));

export const scoreArmy = (army: Card[]): number =>
  army
    .filter(isSphinx)
    .reduce(
      (total, _sphinx, index) =>
        total +
        scoreSphinx(army.filter((card, position) => position !== index)),
      0,
    );

